      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      z-index: 8;
      background: rgba(4,10,18,0.34);
      backdrop-filter: blur(8px);
    }
    .panel {
      width: min(92vw, 420px);
      padding: 24px 20px;
      border-radius: 24px;
      background: linear-gradient(180deg, rgba(18,52,95,0.92), rgba(7,18,35,0.94));
      border: 1px solid rgba(103,232,249,0.26);
      box-shadow: 0 20px 50px rgba(0,0,0,0.35);
      text-align: center;
    }
    .title {
      font-size: 32px;
      font-weight: 900;
      letter-spacing: 1px;
      margin-bottom: 8px;
    }
    .desc {
      font-size: 15px;
      line-height: 1.5;
      opacity: 0.88;
      margin-bottom: 18px;
    }
