  <div id="game">
    <div class="hud">
      <div class="card">
        <div class="label">分数</div>
        <div class="value" id="score">0</div>
      </div>
      <div class="card">
        <div class="label">连击</div>
        <div class="value" id="combo">0</div>
      </div>
      <div class="card">
        <div class="label">剩余</div>
        <div class="value" id="time">20</div>
      </div>
    </div>
    <div id="arena"></div>
    <div class="overlay" id="overlay">
      <div class="panel">
        <div class="title">Link Check</div>
        <div class="desc" id="message">点击屏幕中跳出的信号点得分。连续命中会提升连击，每次命中都会刷新目标位置。</div>
        <div class="big" id="finalScore">0</div>
        <button id="startBtn">开始检查</button>
        <div class="hint">支持触摸和鼠标点击，适配手机竖屏</div>
      </div>
    </div>
  </div>
  <script>
    const arena = document.getElementById('arena');
    const overlay = document.getElementById('overlay');
    const startBtn = document.getElementById('startBtn');
    const scoreEl = document.getElementById('score');
    const comboEl = document.getElementById('combo');
    const timeEl = document.getElementById('time');
    const finalScoreEl = document.getElementById('finalScore');
    const messageEl = document.getElementById('message');

    let score = 0;
    let combo = 0;
    let timeLeft = 20;
    let playing = false;
    let timer = null;
    let target = null;

    function setHud() {
      scoreEl.textContent = score;
      comboEl.textContent = combo;
      timeEl.textContent = timeLeft;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function removeTarget() {
      if (target && target.parentNode) target.parentNode.removeChild(target);
      target = null;
    }

    function spawnTarget() {
      removeTarget();
      const rect = arena.getBoundingClientRect();
      const size = Math.max(74, Math.min(92, rect.width * 0.18));
      const margin = size * 0.6;
      const topSafe = Math.max(120, rect.height * 0.18);
      const x = margin + Math.random() * Math.max(1, rect.width - margin * 2);
      const y = topSafe + Math.random() * Math.max(1, rect.height - topSafe - margin);
      const el = document.createElement('div');
      el.className = 'target';
      el.style.width = size + 'px';
      el.style.height = size + 'px';
      el.style.marginLeft = -(size / 2) + 'px';
      el.style.marginTop = -(size / 2) + 'px';
      el.style.left = x + 'px';
      el.style.top = y + 'px';
      el.addEventListener('pointerdown', hitTarget);
      arena.appendChild(el);
      target = el;
    }

    function showPop(text, x, y) {
      const pop = document.createElement('div');
      pop.className = 'pop';
      pop.textContent = text;
      pop.style.left = x + 'px';
      pop.style.top = y + 'px';
      arena.appendChild(pop);
      setTimeout(() => pop.remove(), 650);
    }

    function hitTarget(e) {
      if (!playing) return;
      e.preventDefault();
      combo += 1;
      const gain = 1 + Math.min(4, Math.floor(combo / 4));
      score += gain;
      setHud();
      const rect = arena.getBoundingClientRect();
      const x = clamp(e.clientX - rect.left, 40, rect.width - 40);
      const y = clamp(e.clientY - rect.top, 80, rect.height - 40);
      showPop('+' + gain, x, y);
      spawnTarget();
    }

    function missTap(e) {
      if (!playing) return;
      if (e.target === target) return;
      combo = 0;
      comboEl.textContent = combo;
    }

    function endGame() {
      playing = false;
      clearInterval(timer);
      removeTarget();
      messageEl.textContent = '检查结束，再来一轮刷新你的最高分。';
      finalScoreEl.textContent = score;
      startBtn.textContent = '重新开始';
      overlay.style.display = 'flex';
    }

    function startGame() {
      score = 0;
      combo = 0;
      timeLeft = 20;
      playing = true;
      overlay.style.display = 'none';
      setHud();
      spawnTarget();
      clearInterval(timer);
      timer = setInterval(() => {
        timeLeft -= 1;
        setHud();
        if (timeLeft <= 0) endGame();
      }, 1000);
    }

    startBtn.addEventListener('click', startGame);
    arena.addEventListener('pointerdown', missTap);
    window.addEventListener('resize', () => {
      if (playing) spawnTarget();
    });
    setHud();
  </script>
</body>
</html>"}

